package com.vandorlabs.neoforge.programmer;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.item.context.*;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.*;
/** Real ItemStack placement and bounded staged-write failures; no canonical registration. */
final class ProgrammerPlacementChecks {
 private static int checks;
 static final NativeProgrammerItem[] FAULTS=new NativeProgrammerItem[8];
 static NativeProgrammerItem fault(NativeProgrammerBlock block,int index){final int failed=index/2;final boolean afterWrite=(index&1)!=0;return FAULTS[index]=new NativeProgrammerItem(block,new Item.Properties()){@Override protected boolean stage(Level world,BlockPos pos,BlockState state){if(state.getValue(NativeProgrammerBlock.PART)==failed){if(afterWrite){super.stage(world,pos,state);if(state.getValue(NativeProgrammerBlock.PART)==0&&world.getBlockEntity(pos) instanceof NativeProgrammerEntity owner){owner.setItem(0,com.vandorlabs.neoforge.credentials.NativeCredentialItems.accessCard(2));need(owner.getItem(0).isEmpty(),"staging observer cannot publish physical inventory");}}return false;}return super.stage(world,pos,state);}};}
 private static void need(boolean value,String reason){checks++;if(!value)throw new AssertionError("Programmer placement: "+reason);}
 private static UseOnContext context(ServerPlayer actor,BlockPos root){return new UseOnContext(actor,InteractionHand.MAIN_HAND,new BlockHitResult(new Vec3(root.getX()+.5,root.getY(),root.getZ()+.5),Direction.UP,root.below(),false));}
 static void run(ServerLevel level,NativeProgrammerBlock block,ServerPlayer actor,BlockPos base){
  int index=0;for(var facing:Direction.Plane.HORIZONTAL)for(boolean creative:new boolean[]{false,true}){var root=base.east(index++*6);level.getChunkAt(root);level.setBlock(root.below(),Blocks.STONE.defaultBlockState(),3);actor.setPos(root.getX()+.5,root.getY(),root.getZ()-3);actor.setYRot(facing.getOpposite().toYRot());actor.setGameMode(creative?net.minecraft.world.level.GameType.CREATIVE:net.minecraft.world.level.GameType.SURVIVAL);var held=new ItemStack(block.asItem(),2);actor.setItemInHand(InteractionHand.MAIN_HAND,held);var use=context(actor,root);var placement=new BlockPlaceContext(use);var result=held.useOn(use);if(!result.consumesAction()){System.out.println("Programmer placement diagnostic root="+root+" selected="+placement.getClickedPos()+" canPlace="+placement.canPlace()+" state="+block.getStateForPlacement(placement)+" mayBuild="+actor.getAbilities().mayBuild+" result="+result);for(int part=0;part<4;part++){var p=NativeProgrammerBlock.cell(root,facing,part);System.out.println("cell="+p+" loaded="+level.hasChunkAt(p)+" replace="+level.getBlockState(p).canBeReplaced(placement)+" state="+level.getBlockState(p)+" be="+level.getBlockEntity(p)+" interact="+level.mayInteract(actor,p)+" use="+actor.mayUseItemAt(p,Direction.UP,held));}}need(result.consumesAction(),"actual item succeeds "+facing+" creative="+creative);need(held.getCount()==(creative?2:1),"exact source consumption");for(int part=0;part<4;part++){var pos=NativeProgrammerBlock.cell(root,facing,part);var state=level.getBlockState(pos);need(state.is(block)&&state.getValue(NativeProgrammerBlock.PART)==part&&state.getValue(NativeProgrammerBlock.FACING)==facing,"source reserved cell metadata");need(part==0?level.getBlockEntity(pos) instanceof NativeProgrammerEntity owner&&!owner.inert():level.getBlockEntity(pos)==null,"sole live root");}level.removeBlock(root,false);}
  actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);actor.setYRot(Direction.SOUTH.toYRot());
  for(int failure=0;failure<4;failure++)for(boolean afterWrite:new boolean[]{false,true}){var root=base.east(64+failure*6+(afterWrite?32:0));level.getChunkAt(root);level.setBlock(root.below(),Blocks.STONE.defaultBlockState(),3);actor.setPos(root.getX()+.5,root.getY(),root.getZ()-3);var stack=new ItemStack(block.asItem(),2);actor.setItemInHand(InteractionHand.MAIN_HAND,stack);var adapter=FAULTS[failure*2+(afterWrite?1:0)];need(!adapter.place(new BlockPlaceContext(context(actor,root))).consumesAction()&&stack.getCount()==2,"failed stage retains item");for(int part=0;part<4;part++)need(level.getBlockState(NativeProgrammerBlock.cell(root,Direction.NORTH,part)).isAir(),"failed stage restores every cell");}
  for(int blocked=0;blocked<4;blocked++){var root=base.east(128+blocked*6);level.getChunkAt(root);level.setBlock(root.below(),Blocks.STONE.defaultBlockState(),3);var obstruction=NativeProgrammerBlock.cell(root,Direction.NORTH,blocked);level.setBlock(obstruction,Blocks.STONE.defaultBlockState(),3);actor.setPos(root.getX()+.5,root.getY(),root.getZ()-3);var held=new ItemStack(block.asItem(),2);actor.setItemInHand(InteractionHand.MAIN_HAND,held);need(!held.useOn(context(actor,root)).consumesAction()&&held.getCount()==2,"blocked member refuses without consumption");for(int part=0;part<4;part++){var pos=NativeProgrammerBlock.cell(root,Direction.NORTH,part);need(part==blocked?level.getBlockState(pos).is(Blocks.STONE):level.getBlockState(pos).isAir(),"blocked footprint unchanged");}level.removeBlock(obstruction,false);}
  for(boolean nativeData:new boolean[]{false,true}){var root=base.east(160+(nativeData?8:0));level.getChunkAt(root);level.setBlock(root.below(),Blocks.STONE.defaultBlockState(),3);actor.setPos(root.getX()+.5,root.getY(),root.getZ()-3);var held=new ItemStack(block.asItem());var raw=new CompoundTag();raw.putString("OpaqueOwner","never install");if(nativeData)held.set(DataComponents.BLOCK_ENTITY_DATA,CustomData.of(raw));else{var wrapper=new CompoundTag();wrapper.put("BlockEntityTag",raw);held.set(DataComponents.CUSTOM_DATA,CustomData.of(wrapper));}actor.setItemInHand(InteractionHand.MAIN_HAND,held);need(!held.useOn(context(actor,root)).consumesAction()&&held.getCount()==1&&level.getBlockState(root).isAir(),"imported physical owner is refused intact");}
  System.out.println("[vandorlabs][programmer-placement] PASS checks="+checks);
 }
}
